const __entriesHydrate = (val) => {
  if(!Array.isArray(val)) return;
  // R5: hydration/echo AND duplicate self-heal go through the production entries-
  // write coordinator, bound to THIS effect run's captured selection context.
  //  • canonicalizes by business-date through the shared helper (revenue/payroll
  //    never summed; nested maps merge by key union, earliest value wins);
  //  • a STALE callback (tenant/business/generation changed) applies nothing;
  //  • an older echo cannot regress a newer pending/committed value (own-echoes
