  //  • a detected duplicate is self-healed via the SAME single-flight pump using
  //    captured-tenant persistence (persistEntries → the explicit-tenant transport),
  //    never the mutable-tenant global write, so it cannot race a supplier write.
  entriesWriteCoordRef.current.onListenerEcho(val, ctxAtSetup);
};

